var sql = "INSERT INTO orders (customer_id, order_date, total_amount, status) VALUES (?, ?, ?, ?)";

try (var conn = dataSource.getConnection();
     var pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

    pstmt.setLong(1, 12345L);                           // customer_id
    pstmt.setDate(2, Date.valueOf(LocalDate.now()));    // order_date
    pstmt.setBigDecimal(3, new BigDecimal("299.99"));  // total_amount
    pstmt.setString(4, "PENDING");                      // status

    int rowsInserted = pstmt.executeUpdate();           // Returns 1 if successful

    if (rowsInserted > 0) {
        try (var generatedKeys = pstmt.getGeneratedKeys()) {
            if (generatedKeys.next()) {
                long orderId = generatedKeys.getLong(1);  // Get the generated ID
                System.out.println("Inserted order with ID: " + orderId);
                // Now you can insert order_items referencing this orderId
            }
        }
    }
} catch (SQLException e) {
    System.err.println("Insert failed: " + e.getMessage());
    throw e;
}

var sql = "INSERT INTO product_inventory (sku, quantity, warehouse_id, last_updated) VALUES (?, ?, ?, ?)";
int batchSize = 1000;  // Commit every 1000 rows
int count = 0;

try (var conn = dataSource.getConnection()) {
    conn.setAutoCommit(false);  // Disable auto-commit for batch efficiency

    try (var pstmt = conn.prepareStatement(sql)) {

        for (var product : productList) {  // Assume productList has 50,000 items
            pstmt.setString(1, product.sku());
            pstmt.setInt(2, product.quantity());
            pstmt.setLong(3, product.warehouseId());
            pstmt.setTimestamp(4, Timestamp.valueOf(LocalDateTime.now()));

            pstmt.addBatch();  // Add to batch instead of executing immediately
            count++;

            if (count % batchSize == 0) {  // Execute batch every 1000 rows
                pstmt.executeBatch();       // Send accumulated statements
                pstmt.clearBatch();         // Clear to free memory
                conn.commit();              // Commit this chunk
            }
        }

        pstmt.executeBatch();  // Execute remaining rows
        conn.commit();         // Final commit

    } catch (SQLException e) {
        conn.rollback();  // Roll back entire batch on error
        throw e;
    }
}

