    pstmt.setTimestamp(4, Timestamp.valueOf(LocalDateTime.now()));  // TIMESTAMP - full datetime
    pstmt.setBoolean(5, true);                         // BOOLEAN - approved

    // Handle optional field - note can be null
    String note = null;
    if (note != null) {
        pstmt.setString(6, note);
    } else {
        pstmt.setNull(6, Types.VARCHAR);  // Explicitly set NULL with SQL type
    }

    pstmt.executeUpdate();
}

