var sql = "INSERT INTO order_items (order_id, product_id, quantity, unit_price) VALUES (?, ?, ?, ?)";
int batchSize = 500;
int count = 0;

try (var conn = dataSource.getConnection()) {
    conn.setAutoCommit(false);  // Disable auto-commit - critical for batch performance

    try (var pstmt = conn.prepareStatement(sql)) {

        for (var item : orderItemList) {  // Assume 20,000 items
            pstmt.setLong(1, item.orderId());
            pstmt.setLong(2, item.productId());
            pstmt.setInt(3, item.quantity());
            pstmt.setBigDecimal(4, item.unitPrice());

            pstmt.addBatch();  // Queue this statement
            count++;

            if (count % batchSize == 0) {
                int[] results = pstmt.executeBatch();  // Execute this chunk
                pstmt.clearBatch();                    // Clear to free memory
                conn.commit();                         // Commit every 500 rows
                System.out.println("Inserted " + count + " rows so far");
            }
        }

        // Execute remaining rows (if total not divisible by batchSize)
        int[] results = pstmt.executeBatch();
        conn.commit();
        System.out.println("Batch complete. Total rows: " + count);

    } catch (SQLException e) {
        conn.rollback();  // Roll back all uncommitted work on error
        System.err.println("Batch failed at row " + count + ": " + e.getMessage());
        throw e;
    }
} finally {
    // Connection auto-closed by try-with-resources
