// Insert parent order and retrieve the generated order_id
var orderSql = "INSERT INTO orders (customer_id, order_date, total_amount) VALUES (?, ?, ?)";
long orderId;

try (var conn = dataSource.getConnection();
     var orderStmt = conn.prepareStatement(orderSql, Statement.RETURN_GENERATED_KEYS)) {

    orderStmt.setLong(1, 12345L);  // customer_id
    orderStmt.setDate(2, Date.valueOf(LocalDate.now()));
    orderStmt.setBigDecimal(3, new BigDecimal("599.99"));

    int rowsInserted = orderStmt.executeUpdate();

    if (rowsInserted > 0) {
        try (var generatedKeys = orderStmt.getGeneratedKeys()) {
            if (generatedKeys.next()) {
                orderId = generatedKeys.getLong(1);  // Get generated order_id
                System.out.println("Created order: " + orderId);
            } else {
                throw new SQLException("Insert succeeded but no ID was generated");
            }
        }
    } else {
        throw new SQLException("Order insert failed");
    }
}

// Now insert child order_items using the retrieved orderId
var itemSql = "INSERT INTO order_items (order_id, product_id, quantity, price) VALUES (?, ?, ?, ?)";
try (var conn = dataSource.getConnection();
     var itemStmt = conn.prepareStatement(itemSql)) {

    itemStmt.setLong(1, orderId);  // Foreign key to parent order
    itemStmt.setLong(2, 7890L);    // product_id
    itemStmt.setInt(3, 2);         // quantity
    itemStmt.setBigDecimal(4, new BigDecimal("299.99"));
    itemStmt.executeUpdate();
}

// PostgreSQL stored procedure signature:
// CREATE PROCEDURE calculate_order_total(IN p_order_id BIGINT, OUT p_total NUMERIC)

// Java code to call it:
var sql = "{call calculate_order_total(?, ?)}";

try (var conn = dataSource.getConnection();
     var cstmt = conn.prepareCall(sql)) {

    // Set IN parameter - order_id
    cstmt.setLong(1, 5001L);

    // Register OUT parameter - total amount
    cstmt.registerOutParameter(2, Types.NUMERIC);

    // Execute the stored procedure
    cstmt.execute();

    // Retrieve the OUT parameter value
    var totalAmount = cstmt.getBigDecimal(2);
    System.out.println("Order total: " + totalAmount);
}

// Calling a function that returns a value:
// CREATE FUNCTION get_customer_tier(p_customer_id BIGINT) RETURNS VARCHAR
var functionSql = "{? = call get_customer_tier(?)}";

try (var conn = dataSource.getConnection();
     var cstmt = conn.prepareCall(functionSql)) {

    // Register function return value (index 1)
    cstmt.registerOutParameter(1, Types.VARCHAR);

    // Set IN parameter (index 2)
    cstmt.setLong(2, 12345L);

    cstmt.execute();

    var tier = cstmt.getString(1);  // Get function return value
    System.out.println("Customer tier: " + tier);
}
